import assert from 'node:assert/strict';
import {mkdir,writeFile,readFile,open,link,unlink} from 'node:fs/promises';
import {join,resolve,dirname,basename} from 'node:path';
import {pathToFileURL} from 'node:url';
import {randomUUID,createHash} from 'node:crypto';
export async function runAcceptedRenewalFinancial({sourceRoot,operationRoot,handoverPath,caseDirectory=null,producerResultPath=null,sourceCommit=null}){
if(!sourceRoot||!operationRoot||!handoverPath)throw new Error('sourceRoot, operationRoot and handoverPath are required');
if(sourceCommit!==null&&!/^[0-9a-f]{40}$/.test(sourceCommit))throw new Error('Use the original source commit SHA');
sourceRoot=resolve(sourceRoot);operationRoot=resolve(operationRoot);handoverPath=resolve(handoverPath);
const load=path=>import(pathToFileURL(join(sourceRoot,path)));
const support='stellar/scf-starforge-20261009/sf74-merchant-support-console/';
const accounting='stellar/scf-starforge-20261009/merchant-settlement-accounting/';
const {openCaseStore}=await load(support+'case-store.mjs');
const {openAccountingWorkspace}=await load(accounting+'workspace/store.mjs');
const {ReceivablesWorkspace}=await load(accounting+'receivables/store.mjs');
const {ServiceAgreementWorkspace}=await load(accounting+'service-agreements/store.mjs');
const {createServiceAgreementsServer}=await load(accounting+'service-agreements/server.mjs');
const {createServiceAgreementClient}=await load(accounting+'service-agreements/client.mjs');
const digest=value=>createHash('sha256').update(value).digest('hex');
const json=value=>JSON.stringify(value,null,2)+'\n';
const save=async(path,value)=>{
 const bytes=Buffer.isBuffer(value)?value:Buffer.from(typeof value==='string'?value:json(value));
 const temporary=join(dirname(path),'.'+basename(path)+'.'+randomUUID()+'.part');
 let handle;
 try{
  handle=await open(temporary,'wx',0o600);await handle.writeFile(bytes);await handle.sync();await handle.close();handle=null;
  await link(temporary,path);
  const directoryHandle=await open(dirname(path),'r');try{await directoryHandle.sync();}finally{await directoryHandle.close();}
 }finally{await handle?.close();await unlink(temporary).catch(error=>{if(error.code!=='ENOENT')throw error;});}
};
function sourceStrKey(version, fill) {
  const bytes = Buffer.alloc(35, fill); bytes[0] = version;
  let crc = 0;
  for (const byte of bytes.subarray(0, 33)) {
    crc ^= byte << 8;
    for (let i = 0; i < 8; i++) crc = ((crc << 1) ^ (crc & 0x8000 ? 0x1021 : 0)) & 65535;
  }
  bytes[33] = crc & 255; bytes[34] = crc >> 8;
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567'; let result = '', bits = 0, acc = 0;
  for (const byte of bytes) {
    acc = (acc << 8) | byte; bits += 8;
    while (bits >= 5) { bits -= 5; result += alphabet[(acc >>> bits) & 31]; }
    acc &= (1 << bits) - 1;
  }
  return result;
}

const financialDirectory=join(operationRoot,'operated-accounting'),
  exportDirectory=join(operationRoot,'agreement-export'),outboxDir=join(operationRoot,'outbox'),
  proofDir=join(operationRoot,'proofs'),termsFile=join(operationRoot,'accounting-terms.json');
await mkdir(operationRoot,{mode:0o700});
for(const d of [exportDirectory,outboxDir,proofDir])await mkdir(d,{mode:0o700});
const renewalJson=await readFile(handoverPath,'utf8');
const acceptedHandover=JSON.parse(renewalJson),caseId=acceptedHandover.case?.id;
if(!caseId)throw new Error('The original handover must include its saved case identity');
const quoteContent=Buffer.from(acceptedHandover.materials.quote.data,'base64').toString('utf8'),
 responseContent=Buffer.from(acceptedHandover.materials.acceptance.data,'base64').toString('utf8');
const producerOutcome=producerResultPath?JSON.parse(await readFile(producerResultPath,'utf8')):{caseId,caseRevision:acceptedHandover.case.revision};
await save(join(operationRoot,'accepted-handover.json'),renewalJson);
await save(join(operationRoot,'accepted-quotation.json'),quoteContent);
await save(join(operationRoot,'accepted-response.json'),responseContent);
if(caseDirectory){
 caseDirectory=resolve(caseDirectory);
 const caseStore=await openCaseStore(caseDirectory);
 await save(join(operationRoot,'operated-case-export.json'),await caseStore.read(caseId));
}
await save(join(operationRoot,'producer-result.json'),producerOutcome);
await save(join(operationRoot,'source-inputs.json'),{sourceRoot,sourceCommit,handoverPath,caseDirectory,producerResultPath,acceptedHandoverSha256:digest(renewalJson)});
await save(termsFile,{schema:'stellar-forge.merchant-accounting-terms.v1',routes:[{
  routeId:'native-renewal',method:'GET',network:'stellar:testnet',asset:sourceStrKey(16,1),payTo:sourceStrKey(48,2),
  amountAtomic:'1000000',unitPriceUsd:'1',unitCostUsd:null,priceBasis:'Original native receiving workspace'
}]});
let workspace=await openAccountingWorkspace({directory:financialDirectory,outboxDir,proofDir,termsFile}),running;
try{
 const receivables=await new ReceivablesWorkspace(workspace).init();
 const agreements=await new ServiceAgreementWorkspace(workspace,{receivables}).init();
 const actor='Native accepted renewal operator';
 const request=value=>({revision:workspace.state.revision,actor,requestId:randomUUID(),...value});
 const customerRequest={revision:workspace.state.revision,actor,reference:'C12-ACCEPTED-RENEWAL',
   name:'Native Journey Merchant',email:'',address:'Original native operating workspace',note:'Retained operational service renewal'};
 await save(join(operationRoot,'request-customer.json'),customerRequest);
 const customer=(await receivables.saveCustomer(customerRequest)).customer;
 const settingsRequest=request({name:'Native service agreement merchant',invoicePrefix:'RN',creditPrefix:'CR'});
 await save(join(operationRoot,'request-settings.json'),settingsRequest);
 await receivables.settings(settingsRequest);
 const createRequest=request({reference:'C12-2026-11',title:'Accepted operational service continuation',customerId:customer.id,
   startDate:'2026-11-01',termMonths:3,billingMonths:1,invoiceTiming:'START',dueDays:30,currencyScale:2,
   quoteContent,responseContent,renewalJson});
 await save(join(operationRoot,'request-agreement-create.json'),createRequest);
 const created=await agreements.create(createRequest),agreementId=created.agreementId;
 const replayRequest={...createRequest,revision:workspace.state.revision};
 await save(join(operationRoot,'request-agreement-replay.json'),replayRequest);
 const replayed=await agreements.create(replayRequest);
 assert.equal(replayed.agreementId,agreementId);
 assert.deepEqual(created.agreement.periods.map(row=>[row.startDate,row.endDate,row.amount]),
   [['2026-11-01','2026-12-01','125.00'],['2026-12-01','2027-01-01','125.00'],['2027-01-01','2027-02-01','125.00']]);
 let assignmentError;
 const duplicateRequest=request({...createRequest,revision:workspace.state.revision,requestId:randomUUID(),reference:'C12-SECOND-CALENDAR'});
 await save(join(operationRoot,'request-duplicate-calendar.json'),duplicateRequest);
 try{await agreements.create(duplicateRequest);}
 catch(error){assignmentError=error;}
 assert.equal(assignmentError?.code,'AGREEMENT_RENEWAL_ALREADY_ASSIGNED');
 assert.equal(assignmentError.details.agreementId,agreementId);
 const preview=await agreements.preview(agreementId,{periodId:'p-0-1',asOf:'2026-11-01'});
 const billRequest=request({expectedVersion:preview.agreementVersion,
   periodId:preview.period.id,previewSha256:preview.previewSha256});
 await save(join(operationRoot,'agreement-billing-preview.json'),preview);
 await save(join(operationRoot,'request-agreement-bill.json'),billRequest);
 const bill=await agreements.bill(agreementId,billRequest);
 const invoicePreview=await receivables.preview(bill.invoice.id);
 const issueRequest=request({expectedVersion:invoicePreview.expectedVersion,
   previewSha256:invoicePreview.previewSha256});
 await save(join(operationRoot,'invoice-preview.json'),invoicePreview);
 await save(join(operationRoot,'request-invoice-issue.json'),issueRequest);
 const issued=await receivables.issue(bill.invoice.id,issueRequest);
 const detail=await agreements.detail(agreementId,{asOf:'2026-11-01'});
 const sourceId=detail.agreement.editions[0].sourceId;
 const originalRenewal=await agreements.sourceFile(agreementId,sourceId,'renewal.json');
 assert.equal(originalRenewal.bytes.toString('utf8'),renewalJson);
 assert.deepEqual(detail.agreement.editions[0].renewal.acceptedHead,acceptedHandover.acceptedHead);
 assert.deepEqual(detail.agreement.editions[0].renewal.servicePeriod,{
   effectiveFrom:'2026-11-01T00:00:00.000Z',effectiveUntil:'2027-02-01T00:00:00.000Z'});
 const exported=await agreements.exportAgreement(agreementId,{asOf:'2026-11-01'});
 for(const file of exported.files){assert(!/[\\/]/.test(file.name));await save(join(exportDirectory,file.name),file.bytes);}
 await save(join(operationRoot,'financial-agreement-detail.json'),detail);
 await workspace.close();workspace=null;
 running=await createServiceAgreementsServer({directory:financialDirectory,port:0});
 const client=createServiceAgreementClient({baseUrl:new URL('/api/service-agreements',running.url).href,fetch});
 const reopened=await client.detail(agreementId,{asOf:'2026-11-01'});
 assert.equal(reopened.workspaceId,detail.workspaceId);assert.equal(reopened.agreement.id,agreementId);
 const download=await fetch(new URL('/api/service-agreements/agreements/'+agreementId+'/export?format=tar&asOf=2026-11-01',running.url));
 assert.equal(download.status,200);
 const tar=Buffer.from(await download.arrayBuffer());await save(join(operationRoot,'accepted-service-agreement.tar'),tar);
 const result={schema:'stellar-forge.accepted-service-renewal-native-result.v1',operation:'SCF-SERVICE-AGREEMENTS-84DF-20261012',
   sourceCommit,result:'complete',node:process.version,
   caseId,caseRevision:producerOutcome.caseRevision,agreementId,workspaceId:detail.workspaceId,
   acceptedHead:acceptedHandover.acceptedHead,servicePeriod:detail.agreement.editions[0].renewal.servicePeriod,
   periodAmounts:reopened.periods.map(row=>({id:row.id,startDate:row.startDate,endDate:row.endDate,amount:row.amount,status:row.status})),
   invoiceId:issued.invoice.id,invoiceNumber:issued.invoice.number,invoiceStatus:issued.invoice.status,
   originalRenewalSha256:digest(renewalJson),sourceFileCount:exported.files.filter(file=>file.name.startsWith('source-'+sourceId+'-')).length,
   exportFiles:exported.files.length,exportTarBytes:tar.length,exportTarSha256:digest(tar),
   duplicateCalendar:{code:assignmentError.code,originalAgreementId:assignmentError.details.agreementId},
   artifacts:{caseDirectory,financialDirectory,exportDirectory,archive:join(operationRoot,'accepted-service-agreement.tar')}};
 await save(join(operationRoot,'native-result.json'),result);
 process.stdout.write(JSON.stringify({phase:'accepted-renewal-native-complete',...result})+'\n');
 return result;
}finally{if(running)await running.close();if(workspace)await workspace.close();}

}

if(process.argv[1]&&import.meta.url===pathToFileURL(resolve(process.argv[1])).href){
 const [sourceRoot,operationRoot,handoverPath,caseDirectory,producerResultPath,sourceCommit]=process.argv.slice(2);
 await runAcceptedRenewalFinancial({sourceRoot,operationRoot,handoverPath,caseDirectory,producerResultPath,sourceCommit});
}

import { buyerExpenseTools, SPECS, PREFIX, workspace, enums, range, text, record, mutation, alias, object, actor, reason, coding, center, labels, period, sha, request, number, date } from './catalog/buyer-expenses.mjs';
export { PREFIX, buyerExpenseTools } from './catalog/buyer-expenses.mjs';
// MIT. Shared customer tool contract; original SF36 methods retain all financial semantics.
import { MAX_RETAINED_CHUNK_BYTES } from './retained-file-reads.mjs';





















export const BUYER_EXPENSE_ACTIONS = Object.freeze(Object.fromEntries(SPECS.map(([name, description, properties, required, readOnly]) =>
  [name, { description, inputSchema: object(properties, required), readOnly }])));

export function validateBuyerExpenseArguments(action,args) {
  const definition=BUYER_EXPENSE_ACTIONS[action];
  const invalid=message=>{throw Object.assign(new Error(message),{code:'BUYER_EXPENSE_ARGUMENTS'});};
  if(!definition)invalid('Choose an original buyer expense action.');
  function visit(value,spec,path) {
    if(spec.enum&&!spec.enum.includes(value))invalid(path+' must use a declared choice.');
    if(spec.type==='object'){
      if(value===null||typeof value!=='object'||Array.isArray(value))invalid(path+' must be an object.');
      if(Object.keys(value).some(k=>!Object.hasOwn(spec.properties,k))||(spec.required??[]).some(k=>!Object.hasOwn(value,k)))invalid(path+' needs exactly its declared fields.');
      for(const [k,v] of Object.entries(value))visit(v,spec.properties[k],path+'.'+k);
    }else if(spec.type==='array'){
      if(!Array.isArray(value)||(spec.minItems!==undefined&&value.length<spec.minItems)||(spec.maxItems!==undefined&&value.length>spec.maxItems))invalid(path+' must be an array within its declared count.');
      value.forEach((v,i)=>visit(v,spec.items,path+'['+i+']'));
    }else if(spec.type==='integer'){
      if(!Number.isSafeInteger(value)||(spec.minimum!==undefined&&value<spec.minimum)||(spec.maximum!==undefined&&value>spec.maximum))invalid(path+' must be an exact whole number within its declared range.');
    }else if(spec.type==='string'){
      if(typeof value!=='string'||(spec.minLength!==undefined&&value.length<spec.minLength)||(spec.maxLength!==undefined&&value.length>spec.maxLength)||(spec.pattern&&!new RegExp(spec.pattern).test(value)))invalid(path+' must preserve its declared original string format.');
    }else if(spec.type==='boolean'&&typeof value!=='boolean')invalid(path+' must be a boolean.');
  }
  visit(args,definition.inputSchema,action);
  if(action==='source_rebind'&&['ledger','quoteSource','governedSource'].filter(key=>Object.hasOwn(args,key)).length!==1)invalid('source_rebind requires exactly one original ledger, quoteSource or governedSource alias.');
  return definition;
}

// MIT. Original tool metadata; provider runtimes load only when selected.
import { MAX_RETAINED_CHUNK_BYTES } from '../retained-file-contracts.mjs';

const PREFIX = 'merchant_buyer_expense_';

const alias = { type: 'string', pattern: '^[a-z0-9][a-z0-9_-]{0,63}$' };

const record = { type: 'string', pattern: '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,159}$' };

const request = { type: 'string', pattern: '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$' };

const sha = { type: 'string', pattern: '^[0-9a-f]{64}$' };

const number = { type: 'integer', minimum: 0 };

const text = (maximum, required = true) => ({ type: 'string', minLength: required ? 1 : 0, maxLength: maximum });

const object = (properties, required = []) => ({ type: 'object', properties, required, additionalProperties: false });

const date = { type: 'string', pattern: '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' };

const range = { offset: number, limit: { type: 'integer', minimum: 1, maximum: 200 } };

const workspace = { workspace: alias };

const mutation = { ...workspace, requestId: request, expectedRevision: number };

const actor = text(240);

const reason = text(4000);

const center = object({ id: record, code: text(100), name: text(200), active: { type: 'boolean' } }, ['code', 'name']);

const period = object({ id: record, name: text(200), from_day: date, through_day: date }, ['name', 'from_day', 'through_day']);

const coding = object({ basis: sha, recognition_date: date, operator: actor, memo: text(4000, false),
  allocations: { type: 'array', minItems: 1, maxItems: 100, items: object({
    center_id: record, amount: { type: 'string', pattern: '^[0-9]+$' },
    project: text(160, false), account_code: text(120, false), memo: text(1000, false)
  }, ['center_id', 'amount']) } }, ['basis', 'recognition_date', 'operator', 'allocations']);

const labels = object({ assets: { type: 'array', items: object({
  network: text(200), asset: text(200), symbol: text(24), decimals: { type: 'integer', minimum: 0, maximum: 30 }
}, ['network', 'asset', 'symbol', 'decimals']) } }, ['assets']);

const enums = values => ({ type: 'string', enum: values });

const SPECS = [
  ['workspaces', 'List the host-declared expense workspaces, original SF36 ledgers, MCP quote sources, exact customer receipts and accountant-return aliases.', {}, [], true],
  ['open', 'Explicitly open the original private expense server and its native lifetime lease. Opening does not capture a source or initiate payment.', workspace, ['workspace'], false],
  ['state', 'Read the original workspace revision and a paged source, cost-center, period or asset-label view.', { ...workspace, view: enums(['summary', 'sources', 'centers', 'periods', 'labels']), ...range }, ['workspace'], true],
  ['items', 'Find native expense rows and exact coding status in the original statement projection.', { ...workspace, query: text(300, false), sourceId: record, status: enums(['ABSENT','RESERVED','UNCODED','STALE','CODED','PAYMENT_UNRESOLVED','FAILED_TRANSACTION','NO_SIGNED_DISPATCH','OBSERVATION_REVIEW','SPENDING_SOURCE_REVIEW','NO_PAYMENT_REQUIRED','ACCOUNTING_UNRESOLVED']), ...range }, ['workspace'], true],
  ['item', 'Inspect one original expense, or page its retained coding editions.', { ...workspace, id: record, view: enums(['current','history']), ...range }, ['workspace','id'], true],
  ['refund_packets', 'Page original customer return receipts and retained source-review decisions, including native accounting exports.', { ...workspace, ...range }, ['workspace'], true],
  ['refund_packet', 'Inspect an original receipt, all native decisions and verified returns, optional store-currency mapping, and matching retained buyer payments.', { ...workspace, id: record }, ['workspace','id'], true],
  ['refund_capture', 'Receive one host-declared customer packet through the unchanged Woo refund receiver. It retains source bytes without any merchant write or new payment.', { ...mutation, refundSource: alias }, ['workspace','requestId','expectedRevision','refundSource'], false],
  ['node_preview', 'Inspect the exact host-declared original Node operation accounting export using its original source/result validators. No ledger or payment operation is run.', {...workspace,nodeSource:alias,operator:actor}, ['workspace','nodeSource','operator'], true],
  ['node_capture', 'Retain the previewed original Node accounting export as a pending source capture in the same expense Store. Review it with capture_review; unpaid and unfinalized results create no allocated expense.', {...mutation,nodeSource:alias,operator:actor,previewSha256:sha}, ['workspace','requestId','expectedRevision','nodeSource','operator','previewSha256'], false],
  ['adjustment_capture', 'Capture a host-declared unchanged original AdjustmentWorkspace export and selected payment/job event. It retains every native decision and verified return without merchant writes or a new payment.', { ...mutation, adjustmentSource: alias }, ['workspace','requestId','expectedRevision','adjustmentSource'], false],
  ['refund_review', 'Accept or reject an original receipt, explicitly bind a proof-backed purchase, or retain a reference-only export without creating expense or returned units.', { ...mutation, id: record,
    payload: object({decision:enums(['ACCEPT','REJECT']),operator:actor,reason,purchase_item_id:record,register_original_purchase:{type:'boolean'}},['decision','operator','reason'])
  }, ['workspace','requestId','expectedRevision','id','payload'], false],
  ['credits', 'Page verified native buyer returns with their original source status, optional independent store-currency credit and operation context.', {...workspace,...range}, ['workspace'], true],
  ['credit', 'Inspect one original return, original purchase allocation, contributing returns or retained coding editions.', {...workspace,id:record,view:enums(['current','history']),...range}, ['workspace','id'], true],
  ['credit_coding_save', 'Allocate the exact original native return against remaining original purchase dimensions; retain the same request ID for recovery.', {...mutation,id:record,payload:coding}, ['workspace','requestId','expectedRevision','id','payload'], false],
  ['captures', 'Page the original captures for a registered source.', { ...workspace, sourceId: record, ...range }, ['workspace','sourceId'], true],
  ['capture_status', 'Inspect the selected original capture and its paged source changes.', { ...workspace, id: record, ...range }, ['workspace','id'], true],
  ['ledger_register', 'Capture and register one host-declared read-only original SF36 ledger. Retain requestId before submission.', { ...mutation, ledger: alias, name: text(160), provenance: text(6000, false) }, ['workspace','requestId','expectedRevision','ledger'], false],
  ['mcp_register', 'Capture and register one host-declared original MCP quote store through its read-only native snapshot reader. Saved native transfer observations remain distinct from buyer response and quote price.', { ...mutation, quoteSource: alias, name: text(160), provenance: text(6000, false) }, ['workspace','requestId','expectedRevision','quoteSource'], false],
  ['governed_mcp_register', 'Capture a host-declared original governed MCP descriptor: original quotes and retained native bindings joined to the complete original SF36 ledger. Outstanding reservations and original settled units remain distinct from saved quote observations.', { ...mutation, governedSource: alias, name: text(160), provenance: text(6000, false) }, ['workspace','requestId','expectedRevision','governedSource'], false],
  ['capture', 'Capture a registered source only when its original locator is declared by this host.', { ...mutation, sourceId: record }, ['workspace','requestId','expectedRevision','sourceId'], false],
  ['source_rebind', 'Rebind the same original source type to exactly one declared ledger, quoteSource or governedSource alias, preserving native identity continuity.', { ...mutation, sourceId: record, ledger: alias, quoteSource: alias, governedSource: alias, operator: actor, reason: text(3000) }, ['workspace','requestId','expectedRevision','sourceId','operator','reason'], false],
  ['capture_review', 'Accept or reject the actual retained source edition with a named reviewer and reason.', { ...mutation, id: record, decision: enums(['ACCEPT','REJECT']), operator: actor, reason: text(3000) }, ['workspace','requestId','expectedRevision','id','decision','operator','reason'], false],
  ['center_save', 'Save an original cost center with its native revision check.', { ...mutation, payload: center }, ['workspace','requestId','expectedRevision','payload'], false],
  ['labels_save', 'Save explicitly supplied native asset labels and scales. Amounts remain exact original base-unit strings.', { ...mutation, payload: labels }, ['workspace','requestId','expectedRevision','payload'], false],
  ['period_save', 'Save an original nonoverlapping accounting period.', { ...mutation, payload: period }, ['workspace','requestId','expectedRevision','payload'], false],
  ['coding_save', 'Save a reviewed original allocation whose base-unit lines exactly equal its settled actual.', { ...mutation, id: record, payload: coding }, ['workspace','requestId','expectedRevision','id','payload'], false],
  ['disposition', 'Resolve a displayed original period issue using its current basis and allowed disposition.', { ...mutation, periodId: record,
    payload: object({ item_id: text(160,false), code: text(240), basis: sha, kind: text(100), reason, operator: actor }, ['item_id','code','basis','kind','reason','operator']) }, ['workspace','requestId','expectedRevision','periodId','payload'], false],
  ['period_report', 'Read a current original period summary or page its exact allocations, exposures, exceptions or native groups.', { ...workspace, id: record, view: enums(['summary','allocations','outstanding_reservations','issues','totals','by_cost_center','by_project','outstanding_totals','source_captures','native_payment_outcomes','credit_allocations','credit_totals','net_totals','credit_by_cost_center','net_by_cost_center','merchant_credit_outcomes','merchant_adjustment_outcomes']), ...range }, ['workspace','id'], true],
  ['period_review', 'Save the named reviewer, capacity and conclusion against the current native period context.', { ...mutation, id: record, reviewer: actor, role: actor, notes: text(6000) }, ['workspace','requestId','expectedRevision','id','reviewer','role','notes'], false],
  ['period_close', 'Issue the original ready period using its exact retained review. Same requestId returns the original committed close.', { ...mutation, id: record, reviewId: record }, ['workspace','requestId','expectedRevision','id','reviewId'], false],
  ['period_reopen', 'Reopen the original closed period with a recorded owner and reason, preserving earlier issued editions.', { ...mutation, id: record, operator: actor, reason }, ['workspace','requestId','expectedRevision','id','operator','reason'], false],
  ['history', 'Page retained period reviews and closes, original activity or successful customer request identities.', { ...workspace, kind: enums(['period','activity','requests']), periodId: record, ...range }, ['workspace','kind'], true],
  ['review', 'Inspect a retained original review and page its frozen data.', { ...workspace, id: record, view: enums(['summary','allocations','outstanding_reservations','issues','totals','by_cost_center','by_project','outstanding_totals','source_captures','native_payment_outcomes','credit_allocations','credit_totals','net_totals','credit_by_cost_center','net_by_cost_center','merchant_credit_outcomes','merchant_adjustment_outcomes']), ...range }, ['workspace','id'], true],
  ['issued', 'Inspect a frozen original accountant edition and page its retained data.', { ...workspace, id: record, view: enums(['summary','allocations','outstanding_reservations','issues','totals','by_cost_center','by_project','outstanding_totals','source_captures','native_payment_outcomes','credit_allocations','credit_totals','net_totals','credit_by_cost_center','net_by_cost_center','merchant_credit_outcomes','merchant_adjustment_outcomes']), ...range }, ['workspace','id'], true],
  ['accountant_returns', 'Page accepted bookkeeping returns for the exact frozen buyer period, preserving prior handoffs and original return identities.', {...workspace,closeId:record,...range}, ['workspace','closeId'], true],
  ['accountant_return', 'Read one accepted buyer bookkeeping return or page its original allocation references and accountant revision chain.', {...workspace,id:record,view:enums(['summary','rows','revisions']),...range}, ['workspace','id'], true],
  ['accountant_preview', 'Review a host-declared SHA-pinned accountant return against its original issued buyer source and currently accepted handoffs. This does not change financial facts.', {...workspace,closeId:record,accountantSource:alias}, ['workspace','closeId','accountantSource'], true],
