}
export function previewAdjustment(detail,value={}){
  need(object(value)&&Object.keys(value).every(key=>REQUEST_FIELDS.includes(key)),'INVALID_ADJUSTMENT_REQUEST','Only the adjustment’s declared fields are accepted.');
