#!/usr/bin/env node
// MIT. Local customer statement API; embeddable in the original accounting runtime.
import {createServer} from 'node:http';
import {readFile} from 'node:fs/promises';
import {fileURLToPath} from 'node:url';
import {join} from 'node:path';
import {openAccountingWorkspace} from '../workspace/store.mjs';
import {CustomerStatementWorkspace,STATEMENT_REQUEST_BYTES} from './store.mjs';
import {need} from './core.mjs';

const PUBLIC=fileURLToPath(new URL('./public/',import.meta.url));
const ASSETS={
  '/customer-statements':['index.html','text/html; charset=utf-8'],
  '/customer-statements/':['index.html','text/html; charset=utf-8'],
  '/customer-statements/index.html':['index.html','text/html; charset=utf-8'],
  '/customer-statements/app.mjs':['app.mjs','text/javascript; charset=utf-8'],
  '/customer-statements/style.css':['style.css','text/css; charset=utf-8']
};
export async function customerStatementAsset(path){
  if(!Object.hasOwn(ASSETS,path))return null;
  const [name,type]=ASSETS[path];return {bytes:await readFile(join(PUBLIC,name)),type};
}
export async function handleCustomerStatementRequest(statements,{method,path,query={},value}){
  const parts=path.split('/').filter(Boolean);
  if(parts[0]!=='api'||parts[1]!=='customer-statements')return null;
  if(parts.length===2&&method==='GET')return {value:await statements.state()};
  if(parts.length===3){
    const action=parts[2];
    if(method==='GET'&&action==='bindings')return {value:await statements.listBindings(query)};
    if(method==='GET'&&action==='statements')return {value:await statements.listStatements(query)};
    if(method==='POST'){
      need(value&&typeof value==='object'&&!Array.isArray(value),'INVALID_STATEMENT_REQUEST','Send a JSON statement request.');
      if(action==='customers')return {value:await statements.saveCustomer(value)};
      if(action==='bindings')return {value:await statements.assign(value)};
      if(action==='usage')return {value:await statements.importUsage(value)};
      if(action==='usage-period')return {value:await statements.previewUsagePeriod(value)};
      if(action==='preview')return {value:await statements.preview(value)};
      if(action==='retain')return {value:await statements.retain(value)};
    }
  }
  if(parts[2]==='statements'&&parts[3]){
    if(parts.length===4&&method==='GET')return {value:await statements.detail(parts[3])};
    if(parts.length===6&&parts[4]==='download'&&method==='GET'){
      const file=await statements.file(parts[3],parts[5]);return {file,type:file.type};
    }
    if(parts.length===5&&parts[4]==='withdraw'&&method==='POST'){
      need(value&&typeof value==='object'&&!Array.isArray(value),'INVALID_STATEMENT_REQUEST','Send a JSON withdrawal request.');
      return {value:await statements.withdraw(parts[3],value)};
    }
  }
  need(false,'STATEMENT_ROUTE_NOT_FOUND','This customer statement operation was not found.',404);
}
async function body(request){
  need(request.headers['content-type']?.split(';')[0].trim()==='application/json','JSON_REQUIRED','Send a JSON operator request.');
  let length=0;const parts=[];
  for await(const part of request){length+=part.length;need(length<=STATEMENT_REQUEST_BYTES,'BODY_TOO_LARGE','The statement request exceeds the supported size.',413);parts.push(part);}
  let value;try{value=JSON.parse(Buffer.concat(parts).toString('utf8'));}catch{need(false,'INVALID_JSON','The statement request is not valid JSON.');}
  need(value&&typeof value==='object'&&!Array.isArray(value),'INVALID_STATEMENT_REQUEST','Send a JSON object.');return value;
}
export async function startCustomerStatementWorkspace({host='127.0.0.1',port=8447,workspace:providedWorkspace,...options}){
  need(['127.0.0.1','localhost'].includes(host),'LOOPBACK_REQUIRED','This customer operator workspace binds to loopback.');
  need(Number.isInteger(port)&&port>=0&&port<=65535,'INVALID_PORT','Choose a valid local port.');
  const workspace=providedWorkspace??await openAccountingWorkspace(options),ownsWorkspace=!providedWorkspace;
  const statements=new CustomerStatementWorkspace(workspace);
  try{await statements.init();}catch(error){if(ownsWorkspace)await workspace.close();throw error;}
  const hosts=new Set();
  const send=(response,status,value,{type='application/json; charset=utf-8',name}={})=>{
    if(response.destroyed)return;
    const bytes=Buffer.isBuffer(value)?value:Buffer.from(JSON.stringify(value));
    response.writeHead(status,{'Content-Type':type,'Content-Length':bytes.length,'Cache-Control':'no-store',
      'X-Content-Type-Options':'nosniff','Referrer-Policy':'no-referrer',
      'Content-Security-Policy':"default-src 'self'; object-src 'none'; frame-ancestors 'none'; base-uri 'none'; form-action 'self'",
      ...(name?{'Content-Disposition':'attachment; filename="'+name+'"'}:{})});response.end(bytes);
  };
  const server=createServer(async(request,response)=>{
    try{
      need(hosts.has(request.headers.host),'INVALID_HOST','Open the printed local customer statement address.',403);
      const url=new URL(request.url,'http://'+request.headers.host),path=url.pathname;
      const asset=request.method==='GET'?await customerStatementAsset(path==='/'?'/customer-statements/':path):null;
      if(asset){send(response,200,asset.bytes,{type:asset.type});return;}
      let value;
      if(request.method==='POST'){
        need(request.headers['x-workspace-request']==='1','WORKSPACE_REQUEST_REQUIRED','Use the local operator form.',403);
        need(!request.headers.origin||request.headers.origin==='http://'+request.headers.host,'INVALID_ORIGIN','Use this local workspace address.',403);
        value=await body(request);
      }
      const result=await handleCustomerStatementRequest(statements,{method:request.method,path,query:Object.fromEntries(url.searchParams),value});
      need(result,'NOT_FOUND','This customer statement route was not found.',404);
      if(result.file)send(response,200,result.file.bytes,{type:result.type??result.file.type,name:result.file.name});
      else send(response,200,result.value);
    }catch(error){
      send(response,error.status??500,{error:{code:error.code??'CUSTOMER_STATEMENT_ERROR',message:error.message??'The customer statement operation failed.'}});
    }
  });
  server.requestTimeout=60000;server.headersTimeout=15000;
  try{
    await new Promise((resolve,reject)=>{server.once('error',reject);server.listen(port,host,()=>{server.removeListener('error',reject);resolve();});});
  }catch(error){if(ownsWorkspace)await workspace.close();throw error;}
  const actualPort=server.address().port;
  hosts.add('127.0.0.1:'+actualPort);hosts.add('localhost:'+actualPort);
  let closing;
  const close=()=>closing??=(async()=>{
    await new Promise((resolve,reject)=>server.close(error=>error?reject(error):resolve()));
    if(ownsWorkspace)await workspace.close();
  })();
  return {server,workspace,statements,url:'http://'+host+':'+actualPort+'/customer-statements/',close};
}

// MIT. Customer statements share the original accounting lease, state and source closure.
import {randomUUID} from 'node:crypto';
import {constants} from 'node:fs';
import {open,mkdir,rename,unlink,lstat} from 'node:fs/promises';
import {join} from 'node:path';
import {STATEMENT_SCHEMA,normalizeCustomer,normalizeUsage,compileCustomerStatement,renderStatementCsv,renderStatementHtml,renderStatementUsageCsv,
  sha,json,need,label,orderReference} from './core.mjs';
import {compileServicePeriod,renderServicePeriodCsv,renderServicePeriodSummaryCsv} from './period-usage.mjs';

const SCHEMA='stellar-forge.merchant-customer-statements-workspace.v1';
const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
const HEX=/^[a-f0-9]{64}$/;
export const MAX_USAGE_BYTES=24_000_000;
export const STATEMENT_REQUEST_BYTES=32_100_000;
const now=()=>new Date().toISOString();
const idValue=(value,name)=>{need(typeof value==='string'&&UUID.test(value),'INVALID_STATEMENT_ID','Choose an existing '+name+'.');return value;};
const actorValue=value=>label(value,'operator',1000);
const object=value=>value&&typeof value==='object'&&!Array.isArray(value);
const pagination=query=>{
  const offset=Number(query.offset??0),limit=Number(query.limit??100);
  need(Number.isSafeInteger(offset)&&offset>=0&&Number.isSafeInteger(limit)&&limit>=1&&limit<=200,
    'INVALID_STATEMENT_PAGE','Use a nonnegative offset and up to 200 rows.');return {offset,limit};
};
function parse(bytes,name){try{return JSON.parse(bytes.toString('utf8'));}catch{need(false,'INVALID_STATEMENT_JSON','Check the '+name+' JSON.');}}
async function readPlain(path,max){
  const handle=await open(path,constants.O_RDONLY|(constants.O_NOFOLLOW??0));
  try{const info=await handle.stat();need(info.isFile()&&info.size>0&&info.size<=max,'STATEMENT_FILE_CHANGED','The retained source file changed.',409);return await handle.readFile();}
  finally{await handle.close();}
}
async function readVerified(path,record,max=128_000_000){
  const bytes=await readPlain(path,max);
  need(sha(bytes)===record.sha256&&(record.bytes===undefined||record.bytes===bytes.length),
    'STATEMENT_FILE_CHANGED','The retained file differs from its recorded hash or byte count.',409);return bytes;
}
async function syncDirectory(path){
  const handle=await open(path,constants.O_RDONLY|(constants.O_DIRECTORY??0)|(constants.O_NOFOLLOW??0));
  try{await handle.sync();}finally{await handle.close();}
}
async function exclusiveFile(path,bytes){
  const handle=await open(path,constants.O_WRONLY|constants.O_CREAT|constants.O_EXCL|(constants.O_NOFOLLOW??0),0o600);
  try{await handle.writeFile(bytes);await handle.sync();}finally{await handle.close();}
}
async function immutableInput(directory,name,bytes){
  const path=join(directory,name);
  try{const current=await readPlain(path,MAX_USAGE_BYTES);need(sha(current)===sha(bytes),'STATEMENT_INPUT_CHANGED','The retained usage input changed.',409);return;}
  catch(error){if(error.code!=='ENOENT')throw error;}
  const temp=join(directory,'.customer-usage-'+randomUUID()+'.tmp');
  try{await exclusiveFile(temp,bytes);await rename(temp,path);await syncDirectory(directory);}
  catch(error){await unlink(temp).catch(()=>{});throw error;}
}
function normalizedIntent(value){
  need(object(value),'INVALID_STATEMENT_REQUEST','Send a statement request.');
  const result={customerId:idValue(value.customerId,'customer'),runId:idValue(value.runId,'completed run'),
    usageId:value.usageId===undefined||value.usageId===null||value.usageId===''?null:idValue(value.usageId,'service usage import'),
    replacesId:value.replacesId===undefined||value.replacesId===null||value.replacesId===''?null:idValue(value.replacesId,'retained statement')};
  if(value.from!==undefined||value.until!==undefined){result.from=value.from;result.until=value.until;}
  if(value.usageOpeningId!==undefined&&value.usageOpeningId!==null&&value.usageOpeningId!==''){
    result.usageOpeningId=idValue(value.usageOpeningId,'opening service usage import');
    need(result.usageId,'SERVICE_PERIOD_CLOSING_REQUIRED','Choose the closing usage capture for this service period.');
  }
  return result;
}

export class CustomerStatementWorkspace{
  constructor(workspace){this.workspace=workspace;}
  async init(){
    return this.workspace.serial(async()=>{
      const state=this.workspace.state;
      if(state.customerStatements===undefined){
        state.customerStatements={schema:SCHEMA,customers:[],bindings:[],imports:[],statements:[],sequence:0};
        await this.workspace.commit('customer_statements_initialized','workspace startup');
      }
      const saved=state.customerStatements;
      need(object(saved)&&saved.schema===SCHEMA&&['customers','bindings','imports','statements'].every(key=>Array.isArray(saved[key]))&&
        Number.isSafeInteger(saved.sequence)&&saved.sequence>=0,'INVALID_CUSTOMER_STATEMENTS','The saved customer statement workspace is invalid.',409);
      return this;
    });
  }
  data(){this.workspace.lease.assertHeld();return this.workspace.state.customerStatements;}
  customer(id){idValue(id,'customer');const row=this.data().customers.find(row=>row.id===id);need(row,'CUSTOMER_NOT_FOUND','Choose a saved customer.',404);return row;}
  statement(id){idValue(id,'statement');const row=this.data().statements.find(row=>row.id===id);need(row,'STATEMENT_NOT_FOUND','Choose a retained statement.',404);return row;}
  usageRow(id){idValue(id,'usage import');const row=this.data().imports.find(row=>row.id===id);need(row,'USAGE_IMPORT_NOT_FOUND','Choose a retained usage import.',404);return row;}
  view(){
    const data=this.data(),counts=new Map();
    for(const row of data.bindings)counts.set(row.customerId,(counts.get(row.customerId)??0)+1);
    return structuredClone({schema:SCHEMA,revision:this.workspace.state.revision,
      customers:data.customers.map(row=>({...row,orders:counts.get(row.id)??0})),
      usageImports:data.imports,usageImportCount:data.imports.length,
      statements:data.statements.slice(0,100),statementCount:data.statements.length,bindingCount:data.bindings.length,
      runs:this.workspace.state.runs.filter(row=>row.status==='complete').map(row=>({id:row.id,name:row.name,status:row.status,createdAt:row.createdAt,
        completedAt:row.completedAt,reportSha256:row.reportSha256,period:row.period??null})),
      history:this.workspace.state.history.filter(row=>row.action.startsWith('customer_')).slice(-80).reverse()});
  }
  async state(){return this.workspace.serial(async()=>this.view());}
  async listBindings(query={}){
    return this.workspace.serial(async()=>{
      const {offset,limit}=pagination(query);
      let rows=this.data().bindings;
      if(query.customerId){this.customer(query.customerId);rows=rows.filter(row=>row.customerId===query.customerId);}
      if(query.search){const search=String(query.search).toLowerCase().slice(0,300);rows=rows.filter(row=>(row.orderRef+'\n'+row.label).toLowerCase().includes(search));}
      return structuredClone({items:rows.slice(offset,offset+limit),total:rows.length,offset,limit,revision:this.workspace.state.revision});
    });
  }
  async listStatements(query={}){
    return this.workspace.serial(async()=>{
      const {offset,limit}=pagination(query);let rows=this.data().statements;
      if(query.customerId){this.customer(query.customerId);rows=rows.filter(row=>row.customerId===query.customerId);}
      if(query.status){need(['RETAINED','WITHDRAWN','SUPERSEDED'].includes(query.status),'INVALID_STATEMENT_STATUS','Choose a document status.');rows=rows.filter(row=>row.status===query.status);}
      return structuredClone({items:rows.slice(offset,offset+limit),total:rows.length,offset,limit,revision:this.workspace.state.revision});
    });
  }
  async saveCustomer(value){
    return this.workspace.serial(async()=>{
      this.workspace.expected(value.revision);const actor=actorValue(value.actor),profile=normalizeCustomer(value),data=this.data();
      const current=value.id?this.customer(value.id):null;
      need(!data.customers.some(row=>row.reference===profile.reference&&row.id!==current?.id),'CUSTOMER_REFERENCE_EXISTS','This customer reference is already assigned.',409);
      if(current){
        need(value.expectedVersion===current.version,'STALE_CUSTOMER','Reload the current customer profile before saving its edited version.',409);
        if(Object.keys(profile).every(key=>profile[key]===current[key]))return {customer:structuredClone(current),state:this.view()};
        Object.assign(current,profile,{version:current.version+1,updatedAt:now(),actor});
      }else{
        need(data.customers.length<1000,'CUSTOMER_LIMIT','This workspace supports 1,000 customer profiles.');
        data.customers.push({...profile,id:randomUUID(),version:1,createdAt:now(),updatedAt:now(),actor});
      }
      const row=current??data.customers.at(-1);
      await this.workspace.commit('customer_profile_saved',actor,{customerId:row.id,version:row.version});
      return {customer:structuredClone(row),state:this.view()};
    });
  }
  async assign(value){
    return this.workspace.serial(async()=>{
      this.workspace.expected(value.revision);const actor=actorValue(value.actor),customer=this.customer(value.customerId),data=this.data();
      need(Array.isArray(value.orders)&&value.orders.length>0&&value.orders.length<=2000,'INVALID_ORDER_ASSIGNMENTS','Assign between one and 2,000 original order references.');
      need(value.reassign===undefined||typeof value.reassign==='boolean','INVALID_ORDER_REASSIGNMENT','Choose whether to reassign existing customer orders.');
      const reason=label(value.reason??'','assignment reason',2000,true),seen=new Set();
      const rows=value.orders.map(row=>{
        need(object(row),'INVALID_ORDER_ASSIGNMENT','Check the original order assignment.');
        const orderRef=orderReference(row.orderRef);need(!seen.has(orderRef),'DUPLICATE_ORDER_ASSIGNMENT','List each order once.');seen.add(orderRef);
        const current=data.bindings.find(item=>item.orderRef===orderRef);
        if(current&&current.customerId!==customer.id)need(value.reassign===true&&reason.length>0,
          'ORDER_ALREADY_ASSIGNED','This original order belongs to another customer. Choose explicit reassignment and enter the correction reason.',409);
        return {orderRef,label:label(row.label??'','customer-facing description',300,true),current};
      });
      need(data.bindings.length+rows.filter(row=>!row.current).length<=20000,'ORDER_BINDING_LIMIT','This workspace supports 20,000 original customer order assignments.');
      const changes=[];
      for(const row of rows){
        const current=row.current;
        if(current?.customerId===customer.id&&current.label===row.label)continue;
        if(current){
          need(current.history.length<200,'ORDER_ASSIGNMENT_HISTORY_LIMIT','This order has reached its retained assignment history limit.');
          const previous={customerId:current.customerId,label:current.label,version:current.version};
          current.history.push({at:now(),actor,reason,previous});
          Object.assign(current,{customerId:customer.id,label:row.label,version:current.version+1,updatedAt:now(),actor});
          changes.push({bindingId:current.id,previousCustomerId:previous.customerId,version:current.version});
        }else{
          const created={id:randomUUID(),orderRef:row.orderRef,orderReferenceDigest:sha(row.orderRef),customerId:customer.id,label:row.label,
            version:1,createdAt:now(),updatedAt:now(),actor,history:[]};
          data.bindings.push(created);changes.push({bindingId:created.id,version:1});
        }
      }
      if(changes.length)await this.workspace.commit('customer_orders_assigned',actor,{customerId:customer.id,changes,reason});
      return {assigned:rows.length,changed:changes.length,state:this.view()};
    });
  }
  async importUsage(value){
    need(typeof value.content==='string'&&Buffer.byteLength(value.content)>0&&Buffer.byteLength(value.content)<=MAX_USAGE_BYTES,
      'SERVICE_USAGE_SIZE','Import a service usage JSON file up to 24 MB.');
    const bytes=Buffer.from(value.content),usage=normalizeUsage(parse(bytes,'service usage')),digest=sha(bytes);
    return this.workspace.serial(async()=>{
      const actor=actorValue(value.actor),name=label(value.name??'Service usage','usage import name',200),data=this.data();
      const prior=data.imports.find(row=>row.sha256===digest);
      if(prior){await this._readUsage(prior);return {import:structuredClone(prior),reused:true,state:this.view()};}
      this.workspace.expected(value.revision);need(data.imports.length<1000,'USAGE_IMPORT_LIMIT','This workspace supports 1,000 retained usage captures.');
      await immutableInput(join(this.workspace.directory,'inputs'),'customer-usage-'+digest+'.json',bytes);
      const record={id:randomUUID(),name,sha256:digest,bytes:bytes.length,createdAt:now(),sourceCreatedAt:usage.createdAt,
        sourceRevision:usage.revision,sourceSchema:usage.sourceSchema,orderCount:usage.orders.length,actor};
      data.imports.unshift(record);
      await this.workspace.commit('customer_service_usage_imported',actor,{importId:record.id,sha256:digest,orderCount:record.orderCount});
      return {import:structuredClone(record),reused:false,state:this.view()};
    });
  }
  async _readUsage(record){
    need(HEX.test(record.sha256),'INVALID_USAGE_RECORD','The saved usage import has an invalid file digest.',409);
    return normalizeUsage(parse(await readVerified(join(this.workspace.directory,'inputs','customer-usage-'+record.sha256+'.json'),record,MAX_USAGE_BYTES),'retained service usage'));
  }
  async _preview(intent){
    const customer=this.customer(intent.customerId),run=this.workspace.runRow(intent.runId);
    need(run.status==='complete','RUN_NOT_COMPLETE','Choose a completed original reconciliation.',409);
    const report=parse(await readVerified(join(this.workspace.runPath(run.id),'report','report.json'),{sha256:run.reportSha256}),'original accounting report');
    let usage=null,usageSource=null,usageOpening=null,usageOpeningSource=null;
    if(intent.usageId){usageSource=this.usageRow(intent.usageId);usage=await this._readUsage(usageSource);}
    if(intent.usageOpeningId){usageOpeningSource=this.usageRow(intent.usageOpeningId);usageOpening=await this._readUsage(usageOpeningSource);}
    if(intent.replacesId){
      const previous=this.statement(intent.replacesId);
      need(previous.customerId===customer.id&&previous.status==='RETAINED','INVALID_STATEMENT_REPLACEMENT','Replace the current retained statement for this same customer.',409);
    }
    const draft=compileCustomerStatement({report,run,customer,bindings:this.data().bindings,usage,usageSource,usageOpening,usageOpeningSource,
      ...(intent.from!==undefined||intent.until!==undefined?{from:intent.from,until:intent.until}:{}),adjustments:this.workspace.state.adjustments??[]});
    if(intent.replacesId)draft.replacesId=intent.replacesId;
    return {intent:structuredClone(intent),draft,previewSha256:sha(json(draft)),revision:this.workspace.state.revision};
  }
  async preview(value){
    const intent=normalizedIntent(value);return this.workspace.serial(async()=>this._preview(intent));
  }
  async previewUsagePeriod(value){
    need(object(value),'INVALID_STATEMENT_REQUEST','Choose the two original usage captures.');
    return this.workspace.serial(async()=>{
      const openingSource=this.usageRow(value.usageOpeningId),closingSource=this.usageRow(value.usageId);
      const opening=await this._readUsage(openingSource),closing=await this._readUsage(closingSource);
      return {period:compileServicePeriod({opening,closing,openingSource,closingSource}),revision:this.workspace.state.revision};
    });
  }
  async retain(value){
    const intent=normalizedIntent(value),actor=actorValue(value.actor),requestId=label(value.requestId,'stable retention request ID',160);
    need(/^[A-Za-z0-9][A-Za-z0-9._:-]{0,159}$/.test(requestId),'INVALID_STATEMENT_REQUEST_ID','Use a stable retention request ID.');
    need(typeof value.previewSha256==='string'&&HEX.test(value.previewSha256),'PREVIEW_REQUIRED','Prepare and review the statement before retaining it.');
    const intentSha256=sha(json({intent,previewSha256:value.previewSha256,actor}));
    return this.workspace.serial(async()=>{
      const data=this.data(),prior=data.statements.find(row=>row.requestId===requestId);
      if(prior){
        need(prior.intentSha256===intentSha256,'STATEMENT_REQUEST_REUSED','This retention request ID already belongs to different statement content.',409);
        return {...await this._detail(prior.id),reused:true,state:this.view()};
      }
      this.workspace.expected(value.revision);need(data.statements.length<5000,'STATEMENT_LIMIT','This workspace supports 5,000 retained customer statements.');
      const preview=await this._preview(intent);
      need(preview.previewSha256===value.previewSha256,'STATEMENT_PREVIEW_CHANGED','The original statement inputs changed. Review a fresh preview before retaining.',409);
      need(preview.draft.items.length>0,'EMPTY_STATEMENT','Resolve the assigned orders or choose a report containing this customer’s original purchases.');
      const createdAt=now(),id=randomUUID(),number='STMT-'+createdAt.slice(0,4)+'-'+String(data.sequence+1).padStart(6,'0');
      const document={...preview.draft,id,number,createdAt,retainedBy:actor,previewSha256:preview.previewSha256};
      const files={
        'statement.json':Buffer.from(json(document)),
        'statement.csv':Buffer.from(renderStatementCsv(document)),
        'usage.csv':Buffer.from(renderStatementUsageCsv(document)),
        'statement.html':Buffer.from(renderStatementHtml(document))
      };
      if(document.servicePeriod){
        files['period.csv']=Buffer.from(renderServicePeriodCsv(document));
        files['period-summary.csv']=Buffer.from(renderServicePeriodSummaryCsv(document));
        for(const [name,sourceId,source] of [
          ['usage-opening.json',intent.usageOpeningId,document.source.usageOpening],
          ['usage-closing.json',intent.usageId,document.source.usage]
        ]){
          const usage=await this._readUsage(this.usageRow(sourceId));
          files[name]=Buffer.from(json({schema:'stellar-forge.merchant-customer-usage-source.v1',source,usage}));
        }
      }
      const metadata=Object.fromEntries(Object.entries(files).map(([name,bytes])=>[name,{sha256:sha(bytes),bytes:bytes.length}]));
      files['manifest.json']=Buffer.from(json({schema:'stellar-forge.merchant-customer-statement-files.v1',id,number,createdAt,
        documentSchema:STATEMENT_SCHEMA,customerId:intent.customerId,files:metadata,source:document.source}));
      metadata['manifest.json']={sha256:sha(files['manifest.json']),bytes:files['manifest.json'].length};
      need(Object.values(metadata).reduce((total,row)=>total+row.bytes,0)<=128_000_000,'STATEMENT_EXPORT_LIMIT','This customer statement exceeds the retained export size limit.');
      const exportsDir=join(this.workspace.directory,'exports'),temporary=join(exportsDir,'.customer-statement-'+id+'.tmp'),target=join(exportsDir,id);
      await mkdir(temporary,{mode:0o700});
      // Unique staged files are fsynced before the original workspace points to them.
      for(const [name,bytes] of Object.entries(files))await exclusiveFile(join(temporary,name),bytes);
      await syncDirectory(temporary);
      await rename(temporary,target);await syncDirectory(exportsDir);
      const record={id,number,requestId,intentSha256,previewSha256:preview.previewSha256,customerId:intent.customerId,
        customerReference:document.customer.reference,customerName:document.customer.name,runId:intent.runId,usageId:intent.usageId,
        ...(document.servicePeriod?{usageOpeningId:intent.usageOpeningId,servicePeriod:{from:document.servicePeriod.from,until:document.servicePeriod.until,orderRef:document.servicePeriod.orderRef}}:{}),
        createdAt,actor,status:'RETAINED',replacesId:intent.replacesId,supersededBy:null,files:metadata,
        orderCount:document.items.length,excludedOrderCount:document.excluded.length,from:document.selection.from,until:document.selection.until,
        history:[{at:createdAt,actor,action:'retained'}]};
      if(intent.replacesId){
        const previous=this.statement(intent.replacesId);previous.status='SUPERSEDED';previous.supersededBy=id;
        previous.history.push({at:createdAt,actor,action:'superseded',statementId:id});
      }
      data.sequence++;data.statements.unshift(record);
      await this.workspace.commit('customer_statement_retained',actor,{statementId:id,number,customerId:intent.customerId,
        reportSha256:document.source.reportSha256,statementSha256:metadata['statement.json'].sha256,replacesId:intent.replacesId});
      return {statement:structuredClone(record),document,reused:false,state:this.view()};
    });
  }
  async _file(id,name){
    const record=this.statement(id);
    if(name==='status.json'){
      const bytes=Buffer.from(json({schema:'stellar-forge.merchant-customer-statement-status.v1',observedAt:now(),
        revision:this.workspace.state.revision,statement:record}));
      return {bytes,name:record.number+'-'+record.status.toLowerCase()+'-status.json',type:'application/json; charset=utf-8'};
    }
    need(Object.hasOwn(record.files,name),'STATEMENT_FILE_NOT_FOUND','Choose a retained statement, CSV, print view or manifest.',404);
    const folder=join(this.workspace.directory,'exports',record.id),folderInfo=await lstat(folder);
    need(folderInfo.isDirectory()&&!folderInfo.isSymbolicLink(),'STATEMENT_DIRECTORY_CHANGED','The retained statement directory changed.',409);
    const bytes=await readVerified(join(folder,name),record.files[name]);
    const type=name.endsWith('.csv')?'text/csv; charset=utf-8':name.endsWith('.html')?'text/html; charset=utf-8':'application/json; charset=utf-8';
    return {bytes,name:record.number+'-'+record.status.toLowerCase()+'-'+name,type};
  }
  async file(id,name){return this.workspace.serial(async()=>this._file(id,name));}
  async _detail(id){
    const statement=structuredClone(this.statement(id));
    const document=parse((await this._file(id,'statement.json')).bytes,'retained statement');
    return {statement,document,revision:this.workspace.state.revision};
  }
  async detail(id){return this.workspace.serial(async()=>this._detail(id));}
  async withdraw(id,value){
    return this.workspace.serial(async()=>{
      this.workspace.expected(value.revision);const actor=actorValue(value.actor),reason=label(value.reason,'withdrawal reason',2000),record=this.statement(id);
      need(record.status==='RETAINED','STATEMENT_ALREADY_CLOSED','Choose a current retained statement to withdraw.',409);
      record.status='WITHDRAWN';record.history.push({at:now(),actor,action:'withdrawn',reason});
      await this.workspace.commit('customer_statement_withdrawn',actor,{statementId:id,reason});
      return {...await this._detail(id),state:this.view()};
    });
  }
}

// MIT. Original saved SF97 pricing report -> original merchant accounting terms.
import {createHash} from 'node:crypto';
import {constants} from 'node:fs';
import {lstat,mkdir,open} from 'node:fs/promises';
import {isAbsolute,join,resolve} from 'node:path';
import {compileTerms} from './reconcile.mjs';

export const PRICING_IMPORT_SCHEMA='stellar-forge.merchant-pricing-import.v1';
export const MAX_PRICING_REPORT_BYTES=64*1024*1024;
export const MAX_ACCOUNTING_TERMS_BYTES=200_000;
const REPORT_SCHEMA='stellar-forge.merchant-revenue-ops.v1';
const TERMS_SCHEMA='stellar-forge.merchant-accounting-terms.v1';
const hash=bytes=>createHash('sha256').update(bytes).digest('hex');
const json=value=>JSON.stringify(value,null,2)+'\n';
const object=value=>value!==null&&typeof value==='object'&&!Array.isArray(value);
const hex64=value=>typeof value==='string'&&/^[a-f0-9]{64}$/.test(value);
const basis=value=>typeof value==='string'&&/^[A-Za-z0-9 _.:/-]{3,100}$/.test(value);
const date=value=>typeof value==='string'&&Number.isFinite(Date.parse(value));
const own=(value,key)=>Object.hasOwn(value,key);

export class PricingImportError extends Error {
  constructor(code,message,details={}){super(message);this.code=code;this.details=details;}
}
function check(ok,code,message,details){
  if(!ok)throw new PricingImportError(code,message,details);
}
function originalReport(report){
  check(object(report)&&report.schema===REPORT_SCHEMA&&Array.isArray(report.routes)&&
    report.routes.length>0&&object(report.overview)&&object(report.sourceSha256),
    'ORIGINAL_PRICING_REPORT_REQUIRED','Choose the original saved SF97 report/report.json, not its merchant terms file.');
  check(typeof report.merchantName==='string'&&report.merchantName.length>0&&
    report.merchantName.length<=160&&date(report.generatedAt)&&
    date(report.observedFrom)&&date(report.observedUntil),
    'INVALID_PRICING_REPORT','The original report is missing its merchant or observation identity.');
  for(const key of ['seller','terms','snapshot'])
    check(hex64(report.sourceSha256[key]),'MISSING_PRICING_SOURCE_HASH','The original report must retain its '+key+' source hash.');
  const kind=report.observationKind??'SESSION';
  check(['SESSION','DURABLE_HISTORY'].includes(kind),'INVALID_OBSERVATION_KIND','Unsupported pricing observation kind.');
  if(kind==='DURABLE_HISTORY'){
    check(hex64(report.sourceSha256.history)&&report.sourceSha256.history===report.sourceSha256.snapshot&&
      object(report.usageHistory)&&object(report.usageHistory.range),
      'INVALID_HISTORY_SOURCE','The retained-period report must preserve its original history identity and range.');
  }
  check(report.overview.routeCount===report.routes.length,'INVALID_PRICING_REPORT','The report route count differs from its original rows.');
  return kind;
}

/**
 * Preserve source ordering and map every quoted alternative through compileTerms.
 * The reference is an explicit short accounting label; full original price bases
 * remain in pricingProvenance. No exchange rate or cost allocation is calculated.
 */
export function createAccountingTermsFromPricingReport(report,{accountingReference,reportSha256=null}={}){
  const kind=originalReport(report);
  if(accountingReference!==undefined)
    check(basis(accountingReference),'INVALID_ACCOUNTING_REFERENCE','Use an accounting reference of 3–100 letters, numbers, spaces, or _ . : / -.');
  check(reportSha256===null||hex64(reportSha256),'INVALID_REPORT_HASH','The original report hash must be a SHA-256 hexadecimal digest.');
  const routes=[],sourceRoutes=[],seenRoutes=new Set();
  for(const [routeIndex,route] of report.routes.entries()){
    check(object(route)&&typeof route.routeId==='string'&&typeof route.method==='string'&&
      typeof route.path==='string'&&typeof route.priceBasis==='string'&&
      route.priceBasis.length>=4&&route.priceBasis.length<=300,
      'INVALID_PRICING_ROUTE','The original pricing route is incomplete.',{routeIndex});
    const identity=route.routeId+'\n'+route.method;
    check(!seenRoutes.has(identity),'DUPLICATE_PRICING_ROUTE','The original report repeats a route and method.',{routeId:route.routeId,method:route.method});
    seenRoutes.add(identity);
    const priceBasis=accountingReference??route.priceBasis;
    check(basis(priceBasis),'ACCOUNTING_REFERENCE_REQUIRED',
      'The original price basis for '+route.routeId+' needs a short accounting reference. Supply --reference; its full original text will be retained.',
      {routeId:route.routeId,priceBasis:route.priceBasis});
    const options=own(route,'paymentOptions')?route.paymentOptions:object(route.payment)?[route.payment]:null;
    check(Array.isArray(options)&&options.length>0,'MISSING_PAYMENT_OPTIONS',
      'The original report must retain every payment option for '+route.routeId+'.',{routeId:route.routeId});
    for(const [optionIndex,option] of options.entries()){
      const details={routeId:route.routeId,method:route.method,optionIndex};
      check(object(option)&&option.scheme==='exact','UNSUPPORTED_PAYMENT_OPTION',
        'Only the original exact Stellar payment options can be imported.',details);
      const term={routeId:route.routeId,method:route.method,network:option.network,
        asset:option.asset,payTo:option.payTo,amountAtomic:option.atomicAmount,
        priceBasis,unitPriceUsd:route.quoteUsd,unitCostUsd:route.variablePerFulfilledUsd};
      try{compileTerms({schema:TERMS_SCHEMA,routes:[term]});}
      catch(error){throw new PricingImportError('UNSUPPORTED_PAYMENT_OPTION',
        'Accounting cannot import '+route.routeId+' option '+(optionIndex+1)+': '+error.message,
        {...details,reason:error.message});}
      routes.push(term);
      check(routes.length<=200,'TOO_MANY_ACCOUNTING_OPTIONS',
        'The original accounting engine accepts at most 200 payment options. No options were dropped.');
    }
    sourceRoutes.push({reportRouteIndex:routeIndex,routeId:route.routeId,method:route.method,path:route.path,
      paymentOptionCount:options.length,priceBasis:route.priceBasis,
      quoteUsd:route.quoteUsd,variablePerFulfilledUsd:route.variablePerFulfilledUsd,
      perChallengeUsd:route.perChallengeUsd,paidTargetMonth:route.paidTargetMonth,
      plannedMonthlyTargetGrossUsd:route.plannedMonthlyTargetGrossUsd,
      plannedMonthlyTargetVariableCostUsd:route.plannedMonthlyTargetVariableCostUsd,
      plannedMonthlyTargetContributionBeforeFixedUsd:route.plannedMonthlyTargetContributionBeforeFixedUsd});
  }
  if(own(report.overview,'paymentOptionCount'))
    check(report.overview.paymentOptionCount===routes.length,'INVALID_PRICING_OPTION_COUNT',
      'The report payment-option count differs from its retained options.');
  const terms={schema:TERMS_SCHEMA,routes,pricingProvenance:{
    schema:PRICING_IMPORT_SCHEMA,reportSchema:report.schema,reportSha256,
    merchantName:report.merchantName,generatedAt:report.generatedAt,
    observationKind:kind,originalSellerMode:report.originalSellerMode??'UNKNOWN',
    observedFrom:report.observedFrom,observedUntil:report.observedUntil,
    sessionId:report.sessionId??null,sessionIds:structuredClone(report.sessionIds??(report.sessionId?[report.sessionId]:[])),
    sourceSha256:structuredClone(report.sourceSha256),
    range:kind==='DURABLE_HISTORY'?structuredClone(report.usageHistory.range):null,
    accountingReference:accountingReference??null,
    overview:structuredClone(report.overview),routes:sourceRoutes,
    allocation:{unitQuote:'ORIGINAL_ROUTE_QUOTE',unitVariableCost:'ORIGINAL_PER_FULFILLED_COST',
      monthlyFixedCostsAllocated:false,challengeCostsAllocated:false,monthlyTargetsBecomeSettlements:false}
  }};
  try{compileTerms(terms);}
  catch(error){throw new PricingImportError('INCOMPATIBLE_ACCOUNTING_TERMS',
    'The complete pricing selection cannot be imported: '+error.message,{reason:error.message});}
  check(Buffer.byteLength(json(terms))<=MAX_ACCOUNTING_TERMS_BYTES,'ACCOUNTING_TERMS_TOO_LARGE',
    'The complete terms and retained pricing context exceed the original accounting input limit of 200 KB.');
  return terms;
}

export function preparePricingReportImport(originalBytes,{accountingReference}={}){
  check(typeof originalBytes==='string'||originalBytes instanceof Uint8Array,
    'ORIGINAL_REPORT_BYTES_REQUIRED','Provide the original saved report bytes or UTF-8 JSON text.');
  const reportBytes=Buffer.from(originalBytes);
  check(reportBytes.length>0&&reportBytes.length<=MAX_PRICING_REPORT_BYTES,'PRICING_REPORT_TOO_LARGE',
    'Choose an original saved pricing report up to 64 MiB.');
  let report;
  try{report=JSON.parse(reportBytes.toString('utf8'));}
  catch{throw new PricingImportError('INVALID_REPORT_JSON','The selected pricing report is not valid JSON.');}
  const reportSha256=hash(reportBytes);
  const terms=createAccountingTermsFromPricingReport(report,{accountingReference,reportSha256});
  const termsBytes=Buffer.from(json(terms)),termsSha256=hash(termsBytes);
  return {terms,reportBytes,termsBytes,reportSha256,termsSha256,summary:{
    merchantName:report.merchantName,observationKind:terms.pricingProvenance.observationKind,
    observedFrom:report.observedFrom,observedUntil:report.observedUntil,
    sourceSha256:structuredClone(report.sourceSha256),range:structuredClone(terms.pricingProvenance.range),
    routes:report.routes.length,paymentOptions:terms.routes.length,
    unknownUnitCostOptions:terms.routes.filter(term=>term.unitCostUsd===null).length,
    accountingReference:accountingReference??null,reportBytes:reportBytes.length,termsBytes:termsBytes.length
  }};
}

function absolute(path,label){
  check(typeof path==='string'&&isAbsolute(path)&&resolve(path)===path&&path!=='/',
    'ABSOLUTE_NORMALIZED_PATH_REQUIRED','Use an absolute normalized '+label+' path.');
}
async function readReport(path){
  absolute(path,'report');
  const handle=await open(path,constants.O_RDONLY|(constants.O_NOFOLLOW??0));
  try{
    const info=await handle.stat();
    check(info.isFile()&&info.size>0&&info.size<=MAX_PRICING_REPORT_BYTES,'INVALID_REPORT_FILE',
      'The pricing report must be a nonempty regular file up to 64 MiB.');
    const bytes=Buffer.alloc(info.size);let offset=0;
    while(offset<bytes.length){
      const result=await handle.read(bytes,offset,bytes.length-offset,offset);
      check(result.bytesRead>0,'REPORT_CHANGED','The saved report was truncated while being read.');
      offset+=result.bytesRead;
    }
    const after=await handle.stat();
    check(after.size===info.size&&after.mtimeMs===info.mtimeMs,'REPORT_CHANGED',
      'The saved report changed while being read. Choose its completed immutable version.');
    return bytes;
  }finally{await handle.close();}
}
async function writeNew(path,bytes){
  const handle=await open(path,'wx',0o600);
  try{await handle.writeFile(bytes);await handle.sync();}finally{await handle.close();}
}

export async function writePricingReportImport({reportFile,outputDirectory,accountingReference}){
  absolute(outputDirectory,'new output directory');
  absolute(reportFile,'report');
  check(reportFile!==outputDirectory&&!reportFile.startsWith(outputDirectory+'/'),'OVERLAPPING_IMPORT_PATHS',
    'Keep the original saved report outside the new import directory.');
  const prepared=preparePricingReportImport(await readReport(reportFile),{accountingReference});
  // Validate everything before creating output. Existing directories and files
  // are never replaced; an interrupted partial directory is retained for review.
  await mkdir(outputDirectory,{mode:0o700});
  const directory=await lstat(outputDirectory);
  check(directory.isDirectory()&&!directory.isSymbolicLink()&&!(directory.mode&0o077),
    'PRIVATE_OUTPUT_REQUIRED','The new import directory must have private mode 0700.');
  await writeNew(join(outputDirectory,'pricing-report.json'),prepared.reportBytes);
  await writeNew(join(outputDirectory,'accounting-terms.json'),prepared.termsBytes);
  const manifest={schema:PRICING_IMPORT_SCHEMA,summary:prepared.summary,
    outputs:[
      {name:'pricing-report.json',bytes:prepared.reportBytes.length,sha256:prepared.reportSha256},
      {name:'accounting-terms.json',bytes:prepared.termsBytes.length,sha256:prepared.termsSha256}
    ]};
  const manifestBytes=Buffer.from(json(manifest));
  await writeNew(join(outputDirectory,'manifest.json'),manifestBytes);
  const handle=await open(outputDirectory,'r');
  try{await handle.sync();}finally{await handle.close();}
  return {schema:PRICING_IMPORT_SCHEMA,output:outputDirectory,
    termsFile:join(outputDirectory,'accounting-terms.json'),
    reportSha256:prepared.reportSha256,termsSha256:prepared.termsSha256,
    manifestSha256:hash(manifestBytes),...prepared.summary};
}

