    need(saved && saved.schema === PLAN_SCHEMA && Array.isArray(saved.plans),
      'PAYMENT_PLAN_WORKSPACE_REQUIRED', 'Initialize payment plans in the original accounting workspace.', 409);
    return saved;
  }
  _plan(id) {
    identifier(id, 'payment plan');
