/** Reopening consumes the retained original; it never depends on the former import path. */
export async function readBuyerStartup(directory,state,{buyerSourceFile,buyerSourceSha256}={}){
  const descriptor=buyerStartupDescriptor(directory,state);
  const original=await readOriginal(descriptor.path,{expectedSha256:descriptor.sha256,expectedBytes:descriptor.bytes});
  const checked=validateBuyerStartupBytes(directory,state,original.bytes);
  if(buyerSourceFile!==undefined)await readOriginal(buyerSourceFile,{expectedSha256:descriptor.sha256,expectedBytes:descriptor.bytes});
  need(buyerSourceSha256===undefined||buyerSourceSha256===descriptor.sha256,
    'BUYER_STARTUP_CHANGED','Reopen this workspace with its retained buyer source identity.',409);
  return checked;
}

export function buyerStartupView(directory,state){
  if(accountingSourceMode(state)!=='buyer')return null;
  const descriptor=buyerStartupDescriptor(directory,state);
  const handoffs=(state.accountantHandoffs??[]).filter(row=>row.source?.kind==='buyer-expense-period'&&row.source.reportSha256===descriptor.sha256)
    .map(row=>({id:row.id,name:row.name,actor:row.actor,createdAt:row.createdAt,
      rowCount:row.rowCount,returnedRevisions:row.revisions.length}));
  return {...descriptor,handoffs};
}

// MIT. Immutable recorded-activity definitions and retained closes over native runs.
import {createHash,randomUUID} from 'node:crypto';
import {constants} from 'node:fs';
import {open} from 'node:fs/promises';
import {join} from 'node:path';
import {compileAccountingPeriod} from '../reconcile.mjs';

const now=()=>new Date().toISOString();
const hash=bytes=>createHash('sha256').update(bytes).digest('hex');
const check=(ok,code,message,status=400)=>{if(!ok)throw Object.assign(new Error(message),{code,status});};
const label=(value,name,max=160,empty=false)=>{
  check(typeof value==='string'&&(empty||value.trim().length>0)&&value.trim().length<=max,'INVALID_FIELD','Check '+name+'.');
  return value.trim();
};
const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
const page=query=>{
  const offset=Number(query.offset??0),limit=Number(query.limit??50);
  check(Number.isSafeInteger(offset)&&offset>=0&&Number.isSafeInteger(limit)&&limit>=1&&limit<=200,'INVALID_PAGE','Use a nonnegative offset and up to 200 rows.');
  return {offset,limit};
};
const emptyReview=()=>({status:'open',note:'',assignee:'',actor:'',version:0,updatedAt:null});
const counts=rows=>rows.reduce((result,row)=>{result[row.review.status]++;return result;},{open:0,investigating:0,reviewed:0});

export class PeriodWorkspace{
  constructor(workspace){this.workspace=workspace;}
  view(){const state=this.workspace.state;return {definitions:state.periodDefinitions??[],selection:state.periodSelection??null,closes:state.periodCloses??[]};}
  definition(id){const record=this.workspace.state.periodDefinitions.find(item=>item.id===id);check(record,'PERIOD_NOT_FOUND','Choose a saved recorded-activity period.',404);return record;}
  selection(value=this.workspace.state.periodSelection){
    if(value===null||value===undefined)return null;
    check(value&&typeof value==='object'&&!Array.isArray(value)&&Number.isSafeInteger(value.version),'INVALID_PERIOD_SELECTION','Choose a saved period version.');
    const record=this.definition(value.id),version=record.versions.find(item=>item.version===value.version);
    check(version,'PERIOD_VERSION_NOT_FOUND','Choose an existing saved period version.',404);
    return {periodId:record.id,version:version.version,name:version.name,from:version.from,until:version.until};
  }
  async save({revision,id,expectedVersion,name,from,until,note='',select=false,actor}){
    const workspace=this.workspace;
    return workspace.serial(async()=>{
      workspace.expected(revision);actor=label(actor,'operator',1000);name=label(name,'period name');note=label(note,'period note',2000,true);
      check(typeof select==='boolean','INVALID_PERIOD_SELECTION','Choose whether to select the saved version.');
      const bounds=compileAccountingPeriod({from,until});
      let record=id?this.definition(id):null;
      if(record){
        check(expectedVersion===record.versions.at(-1).version,'STALE_PERIOD','The saved definition changed. Reload its current version before retaining your edited definition.',409);
        check(record.versions.length<1000,'PERIOD_VERSION_LIMIT','This period already retains 1,000 definitions.');
      }else{
        check(workspace.state.periodDefinitions.length<1000,'PERIOD_LIMIT','This workspace already retains 1,000 named periods.');
        record={id:randomUUID(),createdAt:now(),actor,versions:[]};workspace.state.periodDefinitions.unshift(record);
      }
      const version={version:record.versions.length+1,name,...bounds,note,actor,createdAt:now()};
      record.versions.push(version);
      if(select)workspace.state.periodSelection={id:record.id,version:version.version};
      await workspace.commit('accounting_period_saved',actor,{periodId:record.id,version:version.version,from:bounds.from,until:bounds.until,selected:select});
      return {definition:structuredClone(record),version:structuredClone(version),state:workspace.view()};
    });
  }
  async select({revision,selection,actor}){
    const workspace=this.workspace;
    return workspace.serial(async()=>{
      workspace.expected(revision);actor=label(actor,'operator',1000);
      const chosen=this.selection(selection),value=chosen?{id:chosen.periodId,version:chosen.version}:null;
      if(!same(value,workspace.state.periodSelection)){
        workspace.state.periodSelection=value;
        await workspace.commit('accounting_period_selected',actor,{selection:value});
      }
      return workspace.view();
    });
  }
  closeRow(id){const row=this.workspace.state.periodCloses.find(item=>item.id===id);check(row,'PERIOD_CLOSE_NOT_FOUND','Choose a retained period close.',404);return row;}
  async retainClose({revision,runId,name,note='',includeSources=true,actor}){
    const workspace=this.workspace;
    return workspace.serial(async()=>{
      workspace.expected(revision);actor=label(actor,'operator',1000);name=label(name,'close name');note=label(note,'close note',4000,true);
      check(typeof includeSources==='boolean','INVALID_EXPORT','Choose whether the archive includes the retained original source files.');
      const run=workspace.runRow(runId),report=await workspace.report(runId);
      check(run.period&&report.period,'PERIOD_RUN_REQUIRED','Choose a completed run captured with a saved recorded-activity period.');
      check(workspace.state.periodCloses.length<5000,'PERIOD_CLOSE_LIMIT','This workspace already retains 5,000 closes.');
      const prior=workspace.state.periodCloses.find(item=>item.period.periodId===run.period.periodId);
      const close={schema:'stellar-forge.merchant-period-close.v1',id:randomUUID(),revision:(prior?.revision??0)+1,
        previousCloseId:prior?.id??null,name,note,actor,createdAt:now(),period:structuredClone(run.period),scope:report.period};
      // The existing writer freezes the original report, sources, and reviews.
      // Open/investigating exceptions are retained, never converted or suppressed.
      const retained=await workspace.retainExport(runId,{actor,includeSources,close});
      workspace.state.periodCloses.unshift(retained.close);
      await workspace.commit('accounting_period_closed',actor,{closeId:close.id,closeRevision:close.revision,periodId:run.period.periodId,
        periodVersion:run.period.version,runId,exportId:retained.export.id,reviewCounts:retained.close.reviewCounts});
      return {...retained,state:workspace.view()};
    });
  }
  async file(id,name){
    const close=this.closeRow(id),keys={'period-close.json':'closeSha256','review-notes.json':'reviewNotesSha256'};
    const adjustment=['adjustments.json','adjustments.csv','adjustments.html'].includes(name)?close.adjustmentFiles?.[name]:null;
    const expected=adjustment?.sha256??(name==='adjustments.json'?close.adjustmentsSha256:close[keys[name]]);
    check((Object.hasOwn(keys,name)||adjustment||name==='adjustments.json')&&expected,'CLOSE_FILE_NOT_FOUND','Choose the original close metadata, frozen review notes or retained adjustments.',404);
    const path=join(this.workspace.directory,'exports',close.exportId,name),handle=await open(path,constants.O_RDONLY|(constants.O_NOFOLLOW??0));
    let bytes;
    try{const info=await handle.stat();check(info.isFile()&&info.size>0&&info.size<=128_000_000,'CLOSE_FILE_CHANGED','The retained close file changed.',409);bytes=await handle.readFile();}
    finally{await handle.close();}
    check(hash(bytes)===expected&&(adjustment?.bytes===undefined||bytes.length===adjustment.bytes),'CLOSE_FILE_CHANGED','The retained close file changed.',409);
    return {bytes,name};
  }
  async detail(id){
    const close=structuredClone(this.closeRow(id));await this.file(id,'period-close.json');
    const snapshot=JSON.parse((await this.file(id,'review-notes.json')).bytes.toString('utf8'));
    const current=snapshot.exceptions.map(row=>({...row,review:this.workspace.state.notes[row.id]??emptyReview()}));
    return {close,run:structuredClone(this.workspace.runRow(close.runId)),reviewCounts:close.reviewCounts,currentReviewCounts:counts(current),
      changedReviews:snapshot.exceptions.filter((row,index)=>!same(row.review,current[index].review)).length,
      previousClose:close.previousCloseId?structuredClone(this.closeRow(close.previousCloseId)):null};
  }
  async notes(id,query={}){
    const {offset,limit}=page(query),snapshot=JSON.parse((await this.file(id,'review-notes.json')).bytes.toString('utf8'));
    let rows=snapshot.exceptions.map(row=>({...row,currentReview:this.workspace.state.notes[row.id]??emptyReview()}));
    if(query.status)rows=rows.filter(row=>row.review.status===query.status);
    if(query.search){const text=String(query.search).toLowerCase().slice(0,300);rows=rows.filter(row=>JSON.stringify(row).toLowerCase().includes(text));}
    return {items:rows.slice(offset,offset+limit),total:rows.length,offset,limit};
  }
}

export async function handlePeriodRequest(workspace,{method,path,query={},value}){
  const parts=path.split('/').filter(Boolean);
  if(parts[0]!=='api'||parts[1]!=='periods')return null;
  const periods=workspace.periods;
  if(parts.length===2){
    if(method==='GET')return {value:structuredClone(periods.view())};
    if(method==='POST')return {value:await periods.save(value)};
  }
  if(parts.length===3&&parts[2]==='selection'&&method==='POST')return {value:await periods.select(value)};
  if(parts.length===3&&parts[2]==='closes'&&method==='POST')return {value:await periods.retainClose(value)};
  if(parts[2]==='closes'&&parts[3]&&method==='GET'){
    if(parts.length===4)return {value:await periods.detail(parts[3])};
    if(parts.length===5&&parts[4]==='notes')return {value:await periods.notes(parts[3],query)};
    if(parts.length===5&&parts[4]==='download')return {file:await workspace.archive(periods.closeRow(parts[3]).exportId),type:'application/x-tar'};
    if(parts.length===6&&parts[4]==='download')return {file:await periods.file(parts[3],parts[5]),
      type:parts[5].endsWith('.csv')?'text/csv; charset=utf-8':parts[5].endsWith('.html')?'text/html; charset=utf-8':'application/json; charset=utf-8'};
  }
  check(false,'NOT_FOUND','This recorded-activity period operation was not found.',404);
}

// MIT. Retained original pricing reports in the existing accounting workspace.
import {createHash,randomUUID} from 'node:crypto';
import {constants} from 'node:fs';
import {open,rm} from 'node:fs/promises';
import {join} from 'node:path';
import {preparePricingReportImport,MAX_PRICING_REPORT_BYTES,MAX_ACCOUNTING_TERMS_BYTES} from '../pricing.mjs';
import {compileTerms} from '../reconcile.mjs';

export const PRICING_REQUEST_BYTES=Math.ceil(MAX_PRICING_REPORT_BYTES/3)*4+16_384;
const hash=bytes=>createHash('sha256').update(bytes).digest('hex');
const now=()=>new Date().toISOString();
const check=(ok,code,message,status=400)=>{if(!ok)throw Object.assign(new Error(message),{code,status});};
const reviews=workspace=>workspace.state.pricingImports??[];
const label=(value,name,max=160)=>{
  check(typeof value==='string'&&value.trim().length>0&&value.trim().length<=max,'INVALID_FIELD','Check '+name+'.');
  return value.trim();
};
const parse=bytes=>JSON.parse(bytes.toString('utf8'));
const same=(left,right)=>JSON.stringify(left)===JSON.stringify(right);
function row(workspace,id){
  const record=reviews(workspace).find(item=>item.id===id);
  check(record,'PRICING_REVIEW_NOT_FOUND','Choose a retained pricing review.',404);return record;
}
async function read(path,max,expected){
  const handle=await open(path,constants.O_RDONLY|(constants.O_NOFOLLOW??0));
  try{
    const info=await handle.stat();
    check(info.isFile()&&info.size>0&&info.size<=max,'INVALID_PRICING_INPUT','The retained pricing input is not a supported regular file.');
    const bytes=Buffer.alloc(info.size);let offset=0;
    while(offset<bytes.length){const result=await handle.read(bytes,offset,bytes.length-offset,offset);check(result.bytesRead>0,'PRICING_INPUT_CHANGED','The retained pricing input changed.',409);offset+=result.bytesRead;}
    const after=await handle.stat();
    check(after.size===info.size&&after.mtimeMs===info.mtimeMs&&(!expected||hash(bytes)===expected),'PRICING_INPUT_CHANGED','The retained pricing input changed. Choose its original completed version.',409);
    return bytes;
  }finally{await handle.close();}
}
async function writeNew(path,bytes){
  const handle=await open(path,'wx',0o600);
  try{await handle.writeFile(bytes);await handle.sync();}finally{await handle.close();}
}
async function syncDirectory(path){const handle=await open(path,'r');try{await handle.sync();}finally{await handle.close();}}
function originalBytes(encoded){
  check(typeof encoded==='string'&&encoded.length>0&&encoded.length<=Math.ceil(MAX_PRICING_REPORT_BYTES/3)*4&&encoded.length%4===0&&/^[A-Za-z0-9+/]*={0,2}$/.test(encoded),
    'INVALID_PRICING_UPLOAD','Choose the original pricing report JSON up to 64 MiB.');
  const bytes=Buffer.from(encoded,'base64');
  check(bytes.length<=MAX_PRICING_REPORT_BYTES&&bytes.toString('base64')===encoded,'INVALID_PRICING_UPLOAD','The uploaded report bytes could not be read exactly.');return bytes;
}
function publicOptions(terms){
  return [...compileTerms(terms).values()].map(({price,cost,...option})=>option);
}
async function termsInput(workspace,selection){
  const record=selection==='source'?null:workspace.state.termsImports.find(item=>item.id===selection);
  check(selection==='source'||record,'TERMS_NOT_FOUND','Choose original source terms or a retained terms file.',404);
  const bytes=await read(record?join(workspace.directory,'inputs',record.id+'.terms.json'):workspace.state.sources.termsFile,MAX_ACCOUNTING_TERMS_BYTES,record?.sha256);
  const terms=parse(bytes),options=publicOptions(terms);
  return {selection,name:record?.name??'Original source terms',sha256:hash(bytes),bytes,terms,options,
    pricingReviewId:reviews(workspace).find(item=>item.termsId===selection)?.id??null};
}
export class PricingWorkspace{
  constructor(workspace){this.workspace=workspace;}
  async review({revision,name,reportBase64,accountingReference,actor}){
    const workspace=this.workspace;
    return workspace.serial(async()=>{
      workspace.expected(revision);actor=label(actor,'operator',1000);name=label(name,'pricing review name',130);
      if(accountingReference==='')accountingReference=undefined;
      const prepared=preparePricingReportImport(originalBytes(reportBase64),{accountingReference});
      const prior=reviews(workspace).find(item=>item.reportSha256===prepared.reportSha256&&item.termsSha256===prepared.termsSha256);
      if(prior){await this.file(prior.id,'report');await this.file(prior.id,'terms');return {review:structuredClone(prior),duplicate:true,state:workspace.view()};}
      check(reviews(workspace).length<2000,'PRICING_REVIEW_LIMIT','This workspace already retains 2,000 pricing reviews.');
      const id=randomUUID(),path=join(workspace.directory,'inputs',id+'.pricing-report.json');
      await writeNew(path,prepared.reportBytes);
      try{
        const terms=await workspace.retainTerms({name:name+' · accounting',bytes:prepared.termsBytes,actor});
        const record={id,name,actor,createdAt:now(),termsId:terms.id,reportSha256:prepared.reportSha256,termsSha256:prepared.termsSha256,summary:prepared.summary};
        workspace.state.pricingImports??=[];workspace.state.pricingImports.unshift(record);
        await syncDirectory(join(workspace.directory,'inputs'));
        await workspace.commit('pricing_report_reviewed',actor,{reviewId:id,termsId:terms.id,reportSha256:record.reportSha256,termsSha256:record.termsSha256});
        return {review:structuredClone(record),duplicate:false,state:workspace.view()};
      }catch(error){await rm(path,{force:true});throw error;}
    });
  }
  async detail(id){
    const workspace=this.workspace,record=structuredClone(row(workspace,id)),input=await termsInput(workspace,record.termsId);
    check(input.sha256===record.termsSha256,'PRICING_TERMS_CHANGED','The reviewed accounting terms changed.',409);
    return {review:record,selected:workspace.state.termsSelection===record.termsId,options:input.options,provenance:input.terms.pricingProvenance};
  }
  async select(id,{revision,actor}){
    const record=row(this.workspace,id);
    // The existing selector owns the CAS, action history, and future-run choice.
    await this.detail(id);
    await this.file(id,'report');
    return this.workspace.selectTerms({revision,selection:record.termsId,actor});
  }
  async compare(id,baselineSelection){
    const current=await this.detail(id),baseline=await termsInput(this.workspace,baselineSelection);
    const left=new Map(baseline.options.map(option=>[option.optionId,option]));
    const right=new Map(current.options.map(option=>[option.optionId,option]));
    const summary={added:0,removed:0,changed:0,unchanged:0},items=[];
    for(const optionId of new Set([...right.keys(),...left.keys()])){
      const before=left.get(optionId)??null,after=right.get(optionId)??null;
      const fields=before&&after?[...new Set([...Object.keys(before),...Object.keys(after)])].filter(key=>!same(before[key],after[key])):[];
      const status=!before?'added':!after?'removed':fields.length?'changed':'unchanged';summary[status]++;
      items.push({optionId,status,fields,before,after});
    }
    return {current:current.review,baseline:{selection:baseline.selection,name:baseline.name,sha256:baseline.sha256,pricingReviewId:baseline.pricingReviewId},summary,items,
      provenance:{before:baseline.terms.pricingProvenance??null,after:current.provenance}};
  }
  async file(id,name){
    const workspace=this.workspace,record=row(workspace,id);
    check(['report','terms'].includes(name),'PRICING_FILE_NOT_FOUND','Choose the original report or its reviewed accounting terms.',404);
    const report=name==='report',path=join(workspace.directory,'inputs',report?id+'.pricing-report.json':record.termsId+'.terms.json');
    const bytes=await read(path,report?MAX_PRICING_REPORT_BYTES:MAX_ACCOUNTING_TERMS_BYTES,report?record.reportSha256:record.termsSha256);
    return {bytes,name:report?'original-pricing-report-'+id+'.json':'accounting-terms-'+id+'.json'};
  }
  async capture(run,manifest,termsSha256){
    const workspace=this.workspace,record=reviews(workspace).find(item=>item.termsId===run.termsSelection);
    if(!record)return;
    check(record.termsSha256===termsSha256,'PRICING_TERMS_CHANGED','The selected terms no longer match their retained pricing review.',409);
    const file=await this.file(record.id,'report'),path='sources/pricing-report.json';
    await writeNew(join(workspace.runPath(run.id),path),file.bytes);
    manifest.files.push({source:record.name,path,bytes:file.bytes.length,sha256:record.reportSha256});
    manifest.pricing={reviewId:record.id,name:record.name,actor:record.actor,createdAt:record.createdAt,termsId:record.termsId,
      reportSha256:record.reportSha256,termsSha256:record.termsSha256,reportPath:path,summary:structuredClone(record.summary)};
  }
  async runFile(runId,name){
    const workspace=this.workspace,manifest=await workspace.inputManifest(runId);
    check(manifest.pricing,'PRICING_SOURCE_NOT_CAPTURED','This reconciliation has no original pricing-report upload in its source capture.',404);
    check(['report','terms'].includes(name),'PRICING_FILE_NOT_FOUND','Choose the original report or its reviewed accounting terms.',404);
    const report=name==='report',bytes=await read(join(workspace.runPath(runId),report?'sources/pricing-report.json':'sources/terms.json'),
      report?MAX_PRICING_REPORT_BYTES:MAX_ACCOUNTING_TERMS_BYTES,report?manifest.pricing.reportSha256:manifest.pricing.termsSha256);
    return {bytes,name:(report?'captured-pricing-report-':'captured-accounting-terms-')+runId+'.json'};
  }
}

export async function handlePricingRequest(workspace,{method,path,query,value}){
  const parts=path.split('/').filter(Boolean),pricing=workspace.pricing;
  if(path==='/api/pricing/reviews'&&method==='POST')return {value:await pricing.review(value)};
  if(parts.length>=4&&parts[0]==='api'&&parts[1]==='pricing'&&parts[2]==='reviews'){
    const id=parts[3];
    if(parts.length===4&&method==='GET')return {value:await pricing.detail(id)};
    if(parts.length===5&&parts[4]==='selection'&&method==='POST')return {value:await pricing.select(id,value)};
    if(parts.length===5&&parts[4]==='compare'&&method==='GET')return {value:await pricing.compare(id,query.baseline)};
    if(parts.length===6&&parts[4]==='download'&&method==='GET')return {file:await pricing.file(id,parts[5])};
  }
  if(parts.length===6&&parts[0]==='api'&&parts[1]==='runs'&&parts[3]==='pricing'&&parts[4]==='download'&&method==='GET')
    return {file:await pricing.runFile(parts[2],parts[5])};
  return null;
}

