    !/^[\\/]/.test(value)&&!/^[A-Za-z]:/.test(value)&&!/[\\\u0000-\u001f\u007f]/.test(value)&&
    value.split('/').every(part=>part&&part!=='.'&&part!=='..')&&value.split('/').length<=32,
    'CASE_PACKAGE_FILE_NAME','Use a canonical relative file path.');
