    typeof actor==='string'&&actor.trim()&&Buffer.byteLength(actor)<=200&&!/[\x00-\x1f\x7f]/.test(actor),
    'CASE_PACKAGE_RECEIVING_INPUT','Use the original receiving request ID and named operator.');
