async function request(url,{method='GET',body}={}){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),30000);try{const response=await fetch(url,{method,credentials:'omit',cache:'no-store',signal:controller.signal,...(body?{headers:{'content-type':'application/json'},body:JSON.stringify(body)}:{})});let data;try{data=await response.json();}catch{throw Object.assign(new Error('The workspace returned an unreadable response. Retry the same saved operation.'),{uncertain:method!=='GET'});}if(!response.ok)throw Object.assign(new Error(data.detail||data.error||'The operation could not be completed.'),{status:response.status,code:data.error});return data;}catch(error){if(error.name==='AbortError')throw Object.assign(new Error('The workspace has not returned a result yet. Retry the same save to recover it.'),{uncertain:method!=='GET'});throw error;}finally{clearTimeout(timer);}}
