function renderPortfolio(data){state.portfolio=data;const rows=data.rows??[];$('portfolio-rows').replaceChildren();$('portfolio-metrics').replaceChildren();const metrics=[['Agreements',data.summary?.agreements??data.total??rows.length],['Expired',data.summary?.expired??0],['Notice due',data.summary?.noticeDue??0],['Proposed',data.summary?.proposed??0]];for(const [title,value]of metrics){const metric=node('div','','metric');metric.append(node('strong',value),node('span',title));$('portfolio-metrics').append(metric);}if(!rows.length){const row=node('tr'),cell=node('td','No service agreements in the selected period.','empty');cell.colSpan=6;row.append(cell);$('portfolio-rows').append(row);}for(const item of rows){const row=node('tr');if(item.caseId===state.view?.case?.id&&item.termsId===state.termsId)row.className='selected';const name=node('td');name.append(node('strong',item.customer||item.caseName),node('span',item.title,'muted'));const stateCell=node('td'),badge=node('span',item.urgency==='resolved'?label(item.state):label(item.urgency),'badge'+(['expired','notice_due'].includes(item.urgency)?' urgent':''));stateCell.append(badge);if(item.urgency!=='resolved')stateCell.append(node('div',label(item.state),'muted'));const action=node('td'),button=node('button','Open','quiet');button.type='button';button.dataset.openCase=item.caseId;button.addEventListener('click',()=>openCase(item.caseId,{termsId:item.termsId,renewalId:item.renewal?.id??null}).catch(showError));action.append(button);row.append(name,node('td',item.owner),node('td',stamp(item.effectiveUntil)),node('td',stamp(item.noticeAt)),stateCell,action);$('portfolio-rows').append(row);}const total=data.total??rows.length,offset=data.offset??state.offset;$('portfolio-count').textContent=(data.cases??data.caseCount??'')+' saved cases';$('portfolio-pages').textContent=total?'Showing '+(offset+1)+'-'+Math.min(offset+rows.length,total)+' of '+total:'No renewals to show';$('portfolio-previous').disabled=offset===0;$('po