async function loadPortfolio(offset=0){const version=++state.portfolioVersion;const query={asOf:instant($('portfolio-asof').value),through:$('portfolio-through').value+'T23:59:59.999Z',noticeDays:Number($('portfolio-notice').value),offset,limit:state.limit};if($('portfolio-query').value.trim())query.q=$('portfolio-query').value.trim();status('Reading the saved service portfolio...');const data=await request('/api/services/renewals?'+new URLSearchParams(query));if(version!==state.portfolioVersion)return;state.offset=offset;renderPortfolio(data);if(!(data.unavailable??[]).length)status('Service portfolio loaded. Open an agreement to review its continuation.');}
