function renderSelection(){state.preview=null;state.previewInput=null;state.draftVersion++;$('proposal-preview').hidden=true;const renewal=currentRenewal(),head=currentTerms(),source=sourceAgreement(),continuation=renewal?term(renewal.continuationTerms):head?.status==='proposed'&&source?.sha256!==head.sha256?head:null;summary($('agreement-summary'),source?[['Customer',source.customer],['Service',source.title],['Current owner',source.owner],['Current ends',stamp(source.effectiveUntil)],['Service calendar',source.calendar?.timeZone],['Terms state',label(head?.status)]]:[]);$('renewal-list').replaceChildren();const historyRows=(state.view?.renewals??[]).filter(row=>row.sourceTerms.id===state.termsId).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));for(const item of historyRows){const button=node('button','','renewal-item'+(item.id===state.renewalId?' selected':''));button.type='button';button.dataset.openRenewal=item.id;button.append(node('strong',label(item.state)+' / edition '+item.revision),node('span',stamp(item.createdAt),'muted'));button.addEventListener('click',()=>{if(state.pending)return;state.renewalId=item.id;renderSelection();});$('renewal-list').append(button);}if(!historyRows.length)$('renewal-list').append(node('p','No continuation has been prepared.','muted'));$('proposal-title').textContent=renewal?'Continuation terms / edition '+renewal.revision:'Prepare continuation terms';$('renewal-state').textContent=renewal?label(renewal.state):'New renewal';$('renewal-owner').value=renewal?.owner??continuation?.owner??source?.owner??'';$('renewal-actor').value=renewal?.actor??$('renewal-actor').value??state.view?.case.metadata?.owner??'';$('renewal-from').value=controlTime(continuation?.effectiveFrom??source?.effectiveUntil);$('renewal-until').value=controlTime(continuation?.effectiveUntil);$('renewal-notice').value=renewal?.noticeDays??30;$('renewal-notice-at').value=renewal&&renewal.noticeDays===null?controlTime(renewal.noticeAt):'';$('renewal-note').value