  const b = base32(value);
  if (!b || b.length !== 35 || b[0] !== (type === 'C' ? 16 : type === 'G' ? 48 : -1)) return false;
  const check=crc16(b.subarray(0,33));
  return b[33] === (check & 255) && b[34] === (check >> 8);
}
export function checkOriginalTerms(record, payer) {
