  } finally {
    try {
      if(started)await store.transaction(state=>{
        if(state.worker?.instanceId===instanceId){state.worker.status='STOPPED';state.worker.stoppedAt=new Date().toISOString();}
      });
    } finally {await lease.close();}
  }
